s=s.replace("canvas.addEventListener('keydown'", "canvas.addEventListener('pointermove',e=>{if(this.story)return;const b=canvas.getBoundingClientRect(),[x,y]=this.transform.invert([e.clientX-b.left,e.clientY-b.top]);const hit=this.index?.find(x,y,Math.max(10/this.transform.k,this.layout.size));this.hover=hit?.id||null;canvas.style.cursor=hit?'pointer':'grab';const tip=document.getElementById('unit-tip');if(tip){tip.hidden=!hit;if(hit){const p=this.layout.packets.get(hit.id)!;tip.textContent=p.category+' / '+p.members.length+' responses — open unit';}}this.schedule();});\n  canvas.addEventListener('pointerleave',()=>{this.hover=null;document.getElementById('unit-tip')!.hidden=true;this.schedule();});\n  canvas.addEventListener('keydown'")
