s=s.replace("if(size*k>=3&&this.layout.packets", "if(this.hover===p.id){c.strokeStyle='#74edff';c.lineWidth=1/k;c.strokeRect(pos.x-size,pos.y-size,size*2,size*2);}\n    if(size*k>=3&&this.layout.packets")
