pos=s.index(' person(')
s=s[:pos]+" get groups(){return this.layout.groups;}\n positionFor(id:string){return this.current.get(this.layout.respondentUnit.get(id)||id);}\n pause(value:boolean){this.paused=value;if(value){this.advance(this.started+2000);this.duration=0;select(this.canvas).interrupt();}this.schedule();}\n"+s[pos:]
